export function getPhysicsQuestions(year: number): {
  objective: StudyQuestion[];
  theory: StudyQuestion[];
  practical: StudyQuestion[];
} {
  const yearQs = allQuestions.filter((q) => q.year === year);
  return {
    objective: yearQs.filter((q) => q.category === "objective"),
    theory: yearQs.filter((q) => q.category === "theory"),
    practical: yearQs.filter((q) => q.category === "practical"),
  };
}